export function renderChart({host,state,tile,selected,select,persist,render,dragged}){host.replaceChildren();const board=document.createElement('div');board.className='alignment-board';board.tabIndex=0;board.setAttribute('aria-label','Alignment chart. Select a Tatari, then tap to place. Use arrow keys on placed Tatari to move them.');const stage=document.createElement('div');stage.className='alignment-stage';for(const side of ['left','right','top','bottom']){const n=document.createElement('input');n.type='text';n.maxLength=40;n.className='axis-label axis-'+side;n.value=state.chart[side];n.setAttribute('aria-label',side+' axis label');n.oninput=()=>{state.chart[side]=n.value;persist()};board.append(n)}function syncRemove(key){stage.querySelectorAll('.tatari-remove').forEach(n=>n.remove());if(!key||!state.chart.positions[key])return;const p=state.chart.positions[key],b=document.createElement('button');b.type='button';b.className='tatari-remove chart-remove';b.textContent='×';b.setAttribute('aria-label','Return selected Tatari to pool');b.style.left=p.x+'%';b.style.top=p.y+'%';b.onclick=e=>{e.stopPropagation();delete state.chart.positions[key];select(null);persist();render()};stage.append(b)}const coords=e=>{const r=stage.getBoundingClientRect();return {x:Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100)),y:Math.max(0,Math.min(100,(e.clientY-r.top)/r.height*100))}};function place(id,e){state.chart.positions[id]=coords(e);select(null);persist();render()};stage.onclick=e=>{if(selected!==null)place(selected,e)};stage.ondragover=e=>{if(dragged()!==null)e.preventDefault()};stage.ondrop=e=>{e.preventDefault();if(dragged()!==null)place(dragged(),e)};
for(const [key,p] of Object.entries(state.chart.positions)){const n=tile(key);n.classList.add('chart-tatari');n.draggable=false;n.style.left=p.x+'%';n.style.top=p.y+'%';n.style.touchAction='none';n.onclick=e=>{e.stopPropagation();select(key);host.querySelectorAll('.chart-tatari').forEach(b=>b.setAttribute('aria-pressed',String(b===n)));syncRemove(key)};let moving=false;n.onpointerdown=e=>{if(e.button!==0)return;e.stopPropagation();moving=true;n.setPointerCapture(e.pointerId)};n.onpointermove=e=>{if(!moving)return;e.preventDefault();const v=coords(e);state.chart.positions[key]=v;n.style.left=v.x+'%';n.style.top=v.y+'%';if(stage.querySelector('.chart-remove'))syncRemove(key)};n.onpointerup=e=>{if(!moving)return;moving=false;n.releasePointerCapture(e.pointerId);persist()};n.onpointercancel=()=>{moving=false;persist()};n.onkeydown=e=>{const delta=e.shiftKey?5:1;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();e.stopPropagation();const p=state.chart.positions[key];p.x=Math.max(0,Math.min(100,p.x+(e.key==='ArrowLeft'?-delta:e.key==='ArrowRight'?delta:0)));p.y=Math.max(0,Math.min(100,p.y+(e.key==='ArrowUp'?-delta:e.key==='ArrowDown'?delta:0)));n.style.left=p.x+'%';n.style.top=p.y+'%';persist()}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();delete state.chart.positions[key];select(null);persist();render()}};stage.append(n)}syncRemove(selected);board.append(stage);host.append(board)}
